            while (!service.awaitTermination(1, TimeUnit.SECONDS)) {
                // wait
            }
            for (Future<Boolean> result : results) {
                Assert.assertTrue(al + " resulted in a failed call to getcodec within the thread pool", result.get());
            }
        }
    }
}

