    int shortened = 0;
    for (Entry<Key, Value> entry : s) {
        extent = new KeyExtent(entry.getKey().getRow(), entry.getValue());
        if (extent.getEndRow() != null && extent.getEndRow().toString().length() < 14)
            shortened++;
        count++;
