        index++;
        timeCreated++;
    }
    bw.close();
    StatusMaker statusMaker = new StatusMaker(conn);
    statusMaker.setSourceTableName(sourceTable);
    statusMaker.run();
    Scanner s = ReplicationTable.getScanner(conn);
