    ts.exec("compact -t summary2 --sf-no-summary -w");
    output = ts.exec("summaries");
    assertMatches(output, "(?sm).*^.*c:f1\\s+=\\s+1.*$.*");
    assertMatches(output, "(?sm).*^.*c:f2\\s+=\\s+2.*$.*");
    assertMatches(output, "(?sm).*^.*c:f3\\s+=\\s+1.*$.*");
    // check that there are two files, with none missing summary info
    assertMatches(output, "(?sm).*^.*total[:]2[,]\\s+missing[:]0[,]\\s+extra[:]0.*$.*");
    // create a situation where files has summary data outside of tablet
    ts.exec("addsplits -t summary2 r2");
    output = ts.exec("summaries -e r2");
    assertMatches(output, "(?sm).*^.*c:f1\\s+=\\s+1.*$.*");
    assertMatches(output, "(?sm).*^.*c:f2\\s+=\\s+2.*$.*");
    assertMatches(output, "(?sm).*^.*c:f3\\s+=\\s+1.*$.*");
    // check that there are two files, with one having extra summary info
    assertMatches(output, "(?sm).*^.*total[:]2[,]\\s+missing[:]0[,]\\s+extra[:]1.*$.*");
    // compact only the files with extra summary info
    ts.exec("compact -t summary2 --sf-extra-summary -w");
    output = ts.exec("summaries -e r2");
    assertMatches(output, "(?sm).*^.*c:f1\\s+=\\s+1.*$.*");
    assertMatches(output, "(?sm).*^.*c:f2\\s+=\\s+2.*$.*");
    assertNotContains(output, "c:f3");
    // check that there are two files, with none having extra summary info
    assertMatches(output, "(?sm).*^.*total[:]2[,]\\s+missing[:]0[,]\\s+extra[:]0.*$.*");
}

@Test
public void test() throws Exception {
    final String tableName = getUniqueNames(1)[0];
    final Connector c = getConnector();
    c.tableOperations().create(tableName);
    // majc should take 100 * .5 secs
    IteratorSetting it = new IteratorSetting(100, SlowIterator.class);
    SlowIterator.setSleepTime(it, 500);
    c.tableOperations().attachIterator(tableName, it, EnumSet.of(IteratorScope.majc));
    BatchWriter bw = c.createBatchWriter(tableName, new BatchWriterConfig());
    for (int i = 0; i < 100; i++) {
        Mutation m = new Mutation("" + i);
        m.put("", "", new Value());
        bw.addMutation(m);
    }
    bw.flush();
    // start majc
    final AtomicReference<Exception> ex = new AtomicReference<>();
    Thread thread = new Thread() {

        @Override
        public void run() {
            try {
                c.tableOperations().compact(tableName, null, null, true, true);
            } catch (Exception e) {
                ex.set(e);
            }
        }
    };
    thread.start();
    long now = System.currentTimeMillis();
    sleepUninterruptibly(10, TimeUnit.SECONDS);
    // split the table, interrupts the compaction
    SortedSet<Text> partitionKeys = new TreeSet<>();
    partitionKeys.add(new Text("10"));
    c.tableOperations().addSplits(tableName, partitionKeys);
    thread.join();
    // wait for the restarted compaction
    assertTrue(System.currentTimeMillis() - now > 59 * 1000);
    if (ex.get() != null)
        throw ex.get();
}

@Test
public void test() throws Exception {
    String tableName = getUniqueNames(1)[0];
    for (int tn = 0; tn < 2; tn++) {
        Connector connector = getConnector();
        // create a table and put some data in it
        connector.tableOperations().create(tableName);
        BatchWriter bw = connector.createBatchWriter(tableName, new BatchWriterConfig());
        bw.addMutation(m("a"));
        bw.addMutation(m("b"));
        bw.addMutation(m("c"));
        bw.close();
        // take the table offline
        connector.tableOperations().offline(tableName);
        while (!isOffline(tableName, connector)) sleepUninterruptibly(200, TimeUnit.MILLISECONDS);
        // poke a partial split into the metadata table
        connector.securityOperations().grantTablePermission(getAdminPrincipal(), MetadataTable.NAME, TablePermission.WRITE);
        Table.ID tableId = Table.ID.of(connector.tableOperations().tableIdMap().get(tableName));
        KeyExtent extent = new KeyExtent(tableId, null, new Text("b"));
        Mutation m = extent.getPrevRowUpdateMutation();
        TabletsSection.TabletColumnFamily.SPLIT_RATIO_COLUMN.put(m, new Value(Double.toString(0.5).getBytes()));
        TabletsSection.TabletColumnFamily.OLD_PREV_ROW_COLUMN.put(m, KeyExtent.encodePrevEndRow(null));
        bw = connector.createBatchWriter(MetadataTable.NAME, new BatchWriterConfig());
        bw.addMutation(m);
        if (tn == 1) {
            bw.flush();
            Scanner scanner = connector.createScanner(MetadataTable.NAME, Authorizations.EMPTY);
            scanner.setRange(extent.toMetadataRange());
            scanner.fetchColumnFamily(DataFileColumnFamily.NAME);
            KeyExtent extent2 = new KeyExtent(tableId, new Text("b"), null);
            m = extent2.getPrevRowUpdateMutation();
            TabletsSection.ServerColumnFamily.DIRECTORY_COLUMN.put(m, new Value("/t2".getBytes()));
            TabletsSection.ServerColumnFamily.TIME_COLUMN.put(m, new Value("M0".getBytes()));
            for (Entry<Key, Value> entry : scanner) {
                m.put(DataFileColumnFamily.NAME, entry.getKey().getColumnQualifier(), entry.getValue());
            }
            bw.addMutation(m);
        }
        bw.close();
        // bring the table online
        connector.tableOperations().online(tableName);
        // verify the tablets went online
        Scanner scanner = connector.createScanner(tableName, Authorizations.EMPTY);
        int i = 0;
        String[] expected = { "a", "b", "c" };
        for (Entry<Key, Value> entry : scanner) {
            assertEquals(expected[i], entry.getKey().getRow().toString());
            i++;
        }
        assertEquals(3, i);
        connector.tableOperations().delete(tableName);
    }
}

